import type {
  Cart, CreatedCart, CartCompanyContext, CartLineItem, CartSubscriptionPlanItem, CartStatus, PurchaseOrigin, OrderQuote, CheckoutQuote, SubscriptionOrderQuoteLine,
  CheckoutCartParams, CreateCartParams, UpdateCartParams, FindCartsParams,
  StorefrontUpdateCartParams, StorefrontAddCartProductParams, StorefrontCurrentCartParams,
  CartCheckoutRequest, CartPresentationChangedError,
  StorefrontClient, StorefrontDto,
} from "arky-sdk";
import type { ArkyCartCheckoutInput, ArkyCartInput } from "arky-sdk/storefront";
import type * as Public from "arky-sdk/types";

type Assert<T extends true> = T;
type Equal<A, B> = (<T>() => T extends A ? 1 : 2) extends <T>() => T extends B ? 1 : 2 ? true : false;
type Missing<T, K extends PropertyKey> = K extends keyof T ? false : true;
type RequiredNullable<T, K extends keyof T> = {} extends Pick<T, K> ? false : null extends T[K] ? true : false;
type RequiredField<T, K extends keyof T> = {} extends Pick<T, K> ? false : true;

export type CartContracts = [
  Assert<Equal<Cart, Public.Cart>>,
  Assert<Equal<CartStatus, Public.CartStatus>>,
  Assert<Equal<CartStatus["type"], "active" | "abandoned" | "converted" | "merged" | "expired">>,
  Assert<Equal<Cart["origin"], PurchaseOrigin>>,
  Assert<Equal<Cart["line_items"], CartLineItem[]>>,
  Assert<RequiredField<Cart, "customer_id">>,
  Assert<RequiredNullable<Cart, "company">>,
  Assert<Missing<Cart, "company_id">>,
  Assert<Missing<Cart, "company_location_id">>,
  Assert<Missing<Cart, "audience_items">>,
  Assert<Equal<Cart["market_id"], string>>,
  Assert<Equal<Cart["sales_channel_id"], string>>,
  Assert<Missing<Cart, "market">>,
  Assert<Missing<Cart, "customer_session_id">>,
  Assert<Missing<Cart, "created_by_account_id">>,
  Assert<Missing<CreateCartParams, "market">>,
  Assert<Equal<CreatedCart, Public.CreatedCart>>,
  Assert<Equal<CreatedCart["cart"], Cart>>,
  Assert<Equal<CreatedCart["recovery_token"], string>>,
  Assert<Equal<Awaited<ReturnType<StorefrontClient["eshop"]["cart"]["create"]>>, StorefrontDto<CreatedCart>>>,
  Assert<RequiredField<CreateCartParams, "customer_id">>,
  Assert<Equal<CreateCartParams["customer_id"], string>>,
  Assert<Missing<CreateCartParams, "company_id">>,
  Assert<Missing<UpdateCartParams, "customer_id">>,
  Assert<Missing<UpdateCartParams, "company_id">>,
  Assert<Missing<UpdateCartParams, "market">>,
  Assert<Equal<FindCartsParams["statuses"], CartStatus["type"][] | undefined>>,
  Assert<Equal<FindCartsParams["origins"], PurchaseOrigin["type"][] | undefined>>,
  Assert<Equal<FindCartsParams["sort_field"], "created_at" | "updated_at" | undefined>>,
  Assert<Equal<FindCartsParams["sort_direction"], "asc" | "desc" | undefined>>,
  Assert<Equal<UpdateCartParams["company"], CartCompanyContext | null | undefined>>,
  Assert<Equal<UpdateCartParams["market_id"], string | undefined>>,
  Assert<Equal<OrderQuote, Public.OrderQuote>>,
  Assert<Equal<CheckoutQuote, Public.CheckoutQuote>>,
  Assert<Equal<CheckoutQuote["order"], OrderQuote>>,
  Assert<RequiredNullable<CheckoutQuote, "sources">>,
  Assert<RequiredField<CheckoutQuote, "presentation_digest">>,
  Assert<Equal<OrderQuote["subscription_lines"], SubscriptionOrderQuoteLine[]>>,
  Assert<Missing<OrderQuote, "audience_lines">>,
  Assert<Equal<CartSubscriptionPlanItem["price_override"], Public.ManualPrice | null>>,
  Assert<RequiredNullable<OrderQuote, "payment_option_id">>,
  Assert<RequiredField<OrderQuote, "presentation_digest">>,
  Assert<RequiredField<CheckoutCartParams, "presentation_digest">>,
  Assert<RequiredField<CheckoutCartParams, "sources">>,
  Assert<Equal<CheckoutCartParams["sources"], NonNullable<CheckoutQuote["sources"]>>>,
  Assert<RequiredField<CheckoutCartParams, "locale">>,
  Assert<Equal<keyof StorefrontCurrentCartParams, "company">>,
  Assert<Equal<ArkyCartInput["company"], CartCompanyContext | null | undefined>>,
  Assert<Missing<StorefrontUpdateCartParams, "customer_id">>,
  Assert<Missing<StorefrontUpdateCartParams, "store_id">>,
  Assert<Missing<NonNullable<StorefrontUpdateCartParams["line_items"]>[number], "price_override">>,
  Assert<Missing<StorefrontAddCartProductParams["product"], "price_override">>,
  Assert<Equal<CartCheckoutRequest, Public.CartCheckoutRequest>>,
  Assert<Missing<CartCheckoutRequest, "store_id">>,
  Assert<Equal<keyof ArkyCartCheckoutInput, "payment_option_id" | "return_url" | "clear_after_checkout" | "save_payment_method" | "payment_method_terms_version">>,
  Assert<Equal<CheckoutCartParams["save_payment_method"], boolean | undefined>>,
  Assert<Equal<CheckoutCartParams["payment_method_terms_version"], string | undefined>>,
  Assert<Missing<ArkyCartInput, "return_url">>,
  Assert<Equal<CartPresentationChangedError["quote"], CheckoutQuote>>,
  Assert<Equal<Awaited<ReturnType<StorefrontClient["eshop"]["cart"]["pendingCheckout"]>>, CartCheckoutRequest | null>>,
];
